#!/usr/bin/env python3
# THE NUMBERS WALK, sitting 5 — KORACH (2026-09-10; the owner: "Go" after the #124 rereads, on the ruling READ THEN COMPILE): THE INK
# OF Numbers 16:1-18:32, computed from the Tanakh DB, the snapshot store and the shelf's own bytes — never typed. Sitting 4's form
# (shelach_ink.py): the heads found BY POSITION and asserted; coverage computed; every cut by consonants (the misses collected, asserted
# empty); the engine's numeral parser MEASURED against the portion's numbers; the hand's facts as asserts, run all at once by
# assert_driver.py after the measurement pass (korach_measure1.py) printed them; every gloss of a narrative verb the STORE'S OWN
# (words.gloss). Shared by korach_rows_onkelos.py, korach_rows_sifrei.py and write_korach_ledgers.py.
import json, os, re, html, sqlite3, sys, io, contextlib, unicodedata
from collections import Counter
ROOT = '<repo-old>'
DATE = '2026-09-10'
UNITS = [  # (uid, chapter, lo, hi, title, the Sifrei piskaot by position)
    ('num_16_korach', 16, 1, 35, 'Korach\'s taking; the two hundred and fifty censers; Dathan and Abiram\'s refusal; the test of the new creation; the earth\'s mouth and the fire', []),
    ('num_17_plague_staff', 17, 1, 28, 'the censers beaten into the altar\'s covering; the plague and Aaron\'s incense between the dead and the living; the twelve staffs and the almonds', []),
    ('num_18_priest_levite_dues', 18, 1, 32, 'the priests\' and the Levites\' watch; the twenty-four gifts; the firstborn\'s redemption; the covenant of salt; the tithe and the tithe of the tithe', [116, 117, 118, 119, 120, 121, 122]),
]
OUT = {u[0]: f'{ROOT}/logic/oral_triage/{u[0]}_{DATE}.md' for u in UNITS}

def clean(s): return re.sub(r'<[^>]+>', '', html.unescape(s))
sif = json.load(open(f'{ROOT}/Data/sefaria_export/Sifrei_Bamidbar/en.json'))['text']
onk = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_Numbers/en.json'))['text']
onk_he = json.load(open(f'{ROOT}/Data/sefaria_export/Onkelos_Numbers/he.json'))['text']
heads = {}
for p, rows in enumerate(sif, 1):
    if not rows: continue
    m = re.search(r'\((Bamidbar|Devarim)\.? (\d+):(\d+)', clean(rows[0])[:60])
    heads[p] = (m.group(1), int(m.group(2)), int(m.group(3))) if m else None
# THE SHELF'S ROWS ON KORACH, BY POSITION: the Sifrei on Numbers has NO PISKA on chapters 16-17 (computed on every head — the rebellion,
# the earth, the fire, the plague and the staffs read on Onkelos alone, as the spies and the decree were); 116 heads 18:1, 117 18:8,
# 118 18:15, 119 18:20, 120 18:26, 121 18:27, 122 18:30 — seven piskaot on chapter 18, every head in order, none mistyped; 123 opens
# chapter 19 (the heifer — the next portion's).
assert heads[115] == ('Bamidbar', 15, 37) and heads[116] == ('Bamidbar', 18, 1) and heads[117] == ('Bamidbar', 18, 8) and heads[118] == ('Bamidbar', 18, 15), (heads[115], heads[116], heads[117], heads[118])
assert heads[119] == ('Bamidbar', 18, 20) and heads[120] == ('Bamidbar', 18, 26) and heads[121] == ('Bamidbar', 18, 27) and heads[122] == ('Bamidbar', 18, 30) and heads[123] == ('Bamidbar', 19, 1), (heads[119], heads[120], heads[121], heads[122], heads[123])
NO_PISKA_16_17 = sorted(p for p, h in heads.items() if h and h[0] == 'Bamidbar' and h[1] in (16, 17))
assert NO_PISKA_16_17 == [], NO_PISKA_16_17   # the shelf's silence on Korach — computed on every head
assert sorted(p for p, h in heads.items() if h and h[0] == 'Bamidbar' and h[1] == 18) == list(range(116, 123))
assert [p for p in range(113, 127) if heads.get(p) is None] == []   # no headless piska in the stretch
HEAD_FIX = {}
def head(p): return HEAD_FIX.get(p) or heads[p][1:]
PISKAOT = [p for u in UNITS for p in u[5]]
assert PISKAOT == list(range(116, 123)) and len(PISKAOT) == 7
for a, b in zip(PISKAOT, PISKAOT[1:]): assert head(b) >= head(a), (a, b, head(a), head(b))     # monotone by position
for uid, c, lo, hi, _, ps in UNITS:
    for p in ps: assert (c, lo) <= head(p) <= (c, hi), (uid, p, head(p))
SIF_ROWS = {p: len(sif[p - 1]) for p in PISKAOT}
assert SIF_ROWS == {116: 2, 117: 3, 118: 1, 119: 5, 120: 1, 121: 1, 122: 1} and sum(SIF_ROWS.values()) == 14, SIF_ROWS
ONK_LEN = {c: len(onk[c - 1]) for c in range(15, 20)}
assert ONK_LEN == {15: 41, 16: 35, 17: 28, 18: 32, 19: 22} and {c: len(onk_he[c - 1]) for c in range(15, 20)} == ONK_LEN, ONK_LEN
shelf_numbers = sorted(d for d in os.listdir(f'{ROOT}/Data/sefaria_export') if re.search(r'Numbers|Bamidbar', d))
outside = [d for d in shelf_numbers if d not in ('Sifrei_Bamidbar', 'Onkelos_Numbers')]
assert len(outside) == 23, len(outside)
# THE PRIOR READS (grep of logic/oral_triage at the sitting, the sitting's own ledgers excluded): no row of 116-122 read by any prior
# ledger; no Onkelos verse of 16, 17, 18 — FRESH
TRI = f'{ROOT}/logic/oral_triage'
LED = {f: open(f'{TRI}/{f}', encoding='utf-8').read() for f in os.listdir(TRI) if f.endswith('.md') and f'{TRI}/{f}' not in OUT.values()}
prior = sorted(f for f, t in LED.items() if re.search(r'Sifrei Bamidbar (11[6-9]|12[0-2]):\d', t))
assert prior == [], prior
prior_onk = sorted(f for f, t in LED.items() if re.search(r'Onkelos Num (16|17|18):\d', t))
assert prior_onk == [], prior_onk

# ---- THE DRAFTS' SPANS AND THE BOUNDARIES, COMPUTED ----
db = sqlite3.connect(f'file:{ROOT}/elijah_docket/tanakh.sqlite?mode=ro', uri=True)
VC = dict(db.execute("SELECT chapter, COUNT(*) FROM verses WHERE book='Num' GROUP BY chapter").fetchall())
assert VC[16] == 35 and VC[17] == 28 and VC[18] == 32 and VC[19] == 22
def unit_text(uid): return open(f'{ROOT}/logic/units/{uid}.yaml', encoding='utf-8').read()
def steps(uid): return sorted({(int(a), int(b)) for a, b in re.findall(r'STEP_Nm_(\d+)_(\d+)', unit_text(uid))})
for uid, c, lo, hi, _, _ in UNITS:
    st = steps(uid); assert st == [(c, v) for v in range(lo, hi + 1)], (uid, st[:2], st[-2:])
    assert 'status: draft' in unit_text(uid) and 'operators:' not in unit_text(uid), uid
assert 'status: frozen' in unit_text('num_15_offerings_laws') and steps('num_15_offerings_laws') == [(15, v) for v in range(1, 32)]
assert steps('num_19_parah')[0] == (19, 1) and 'status: draft' in unit_text('num_19_parah')   # the next portion opens at 19:1 (Chukat)
SPAN = [(c, v) for (_, c, lo, hi, _, _) in UNITS for v in range(lo, hi + 1)]
assert len(SPAN) == 95 == 35 + 28 + 32 and SPAN[0] == (16, 1) and SPAN[-1] == (18, 32)

# ---- THE INK, computed from the Tanakh DB and the snapshot store ----
def plain(w): return ''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05C7))
def pointed(w): return ''.join(c for c in w if c != '/' and not (0x0591 <= ord(c) <= 0x05AF))
def accents(w): return [unicodedata.name(c).replace('HEBREW ACCENT ', '') for c in w if 0x0591 <= ord(c) <= 0x05AE]
rows = db.execute("SELECT v.book, v.chapter, v.verse, w.he, w.morph FROM words w JOIN verses v ON w.verse_id=v.id ORDER BY v.id, w.idx").fetchall()
by, byp, byraw = {}, {}, {}
for b, c, v, he, m in rows:
    by.setdefault((b, c, v), []).append((plain(he), m)); byp.setdefault((b, c, v), []).append(pointed(he)); byraw.setdefault((b, c, v), []).append(he)
T = ('Gen', 'Exod', 'Lev', 'Num', 'Deut')
def words(b, c, v): return [x for x, _ in by[(b, c, v)]]
def hits(sub, books=None, exact=False): return sorted({f'{b} {c}:{v}' for (b, c, v), ws in by.items() if (books is None or b in books) and any((x == sub) if exact else (sub in x) for x, _ in ws)})
def count_tok(tok, books=None): return sum(1 for (b, c, v), ws in by.items() if (books is None or b in books) for x, _ in ws if x == tok)
def phrase(seq, books=T):
    out = []
    for (b, c, v), ws in by.items():
        if books is not None and b not in books: continue
        w = [x for x, _ in ws]
        if any(w[i:i + len(seq)] == list(seq) for i in range(len(w) - len(seq) + 1)): out.append(f'{b} {c}:{v}')
    return sorted(out)
def nphrase(seq, b, c, v):
    w = words(b, c, v); return sum(1 for i in range(len(w) - len(seq) + 1) if w[i:i + len(seq)] == list(seq))
def key(s):
    b, cv = s.split(' '); c, v = cv.split(':'); return (b, int(c), int(v))
FAIL = []
def H(c, v, *cons):
    """the pointed Hebrew of Num c:v for the consonantal words given, in order — cut from the DB, never typed"""
    w, wp = words('Num', c, v), byp[('Num', c, v)]
    out, i = [], 0
    for k in cons:
        j = i
        while j < len(w) and w[j] != k: j += 1
        if j >= len(w): FAIL.append(('H', c, v, k)); out.append('⟨MISS⟩'); continue
        out.append(wp[j]); i = j + 1
    return ' '.join(out)
def A(c, v, *cons):
    """the pointed Aramaic of Onkelos Num c:v for the consonantal words given — cut from the shelf's own bytes"""
    ws = clean(onk_he[c - 1][v - 1]).rstrip(':').split()
    out, i = [], 0
    for k in cons:
        j = i
        while j < len(ws) and plain(ws[j]) != k: j += 1
        if j >= len(ws): FAIL.append(('A', c, v, k, [plain(x) for x in ws])); out.append('⟨MISS⟩'); continue
        out.append(ws[j]); i = j + 1
    return ' '.join(out)
def aramaic(c, v): return [plain(x) for x in clean(onk_he[c - 1][v - 1]).rstrip(':').split()]
def numword(n): return f'{n:,}'
# THE STORE'S OWN GLOSSES — every English beside a narrative verb is the snapshot store's words.gloss, never typed
store = sqlite3.connect(f'file:{ROOT}/torah_grok.SNAPSHOT-main-51801ca.sqlite?mode=ro', uri=True)
SG = {}
for c, v, hp, g in store.execute("SELECT v.chapter, v.verse, w.he_plain, w.gloss FROM words w JOIN verses v ON w.verse_id=v.id WHERE v.book='Num' AND v.chapter BETWEEN 16 AND 18 ORDER BY v.id, w.idx"):
    SG.setdefault((c, v), []).append((hp.replace('/', ''), g))
def sg(c, v, tok):
    for hp, g in SG[(c, v)]:
        if hp == tok: return g
    raise KeyError((c, v, tok))

# THE ENGINE'S PARSER (taught the census at 1b, the construct and the accent at 2b, the dual, the suffix, the half and the seven-stem
# at 3b, the fraction, the unit noun and the definite one at 4b) on Korach's numbers — MEASURED before the compile is asked
sys.path.insert(0, f'{ROOT}/World/step9')
with contextlib.redirect_stdout(io.StringIO()):
    import cold_run_sequence as CS
def N(b, c, v): return CS.ink_numbers(CS.verse_words(b, c, v))
RIGHT = {k: N('Num', *k) for k in [(16, 2), (16, 15), (16, 17), (16, 22), (17, 14), (17, 17), (17, 18), (17, 21), (18, 16)]}
assert RIGHT == {(16, 2): [250], (16, 15): [1, 1], (16, 17): [250], (16, 22): [1], (17, 14): [14700], (17, 17): [12], (17, 18): [1], (17, 21): [1, 1, 12], (18, 16): [5, 20]}, RIGHT
GAPS = {k: N('Num', *k) for k in [(16, 35)]}
assert GAPS == {(16, 35): [200]}, GAPS   # THE DEFINITE NUMERAL AT THE HEAD OF A CHAIN: "the fifty and two hundred men" — the article on the fifty silences it, the chain reads 200
GAPS_TRUE = {(16, 35): 'the two hundred and fifty men (the article on the first numeral of the compound)'}
NOUNS = {k: N('Num', *k) for k in [(18, 21), (18, 24), (18, 26), (18, 28)]}
assert NOUNS == {(18, 21): [], (18, 24): [], (18, 26): [], (18, 28): []}, NOUNS   # the tithe NOUN silent by 4b's tithe rule (the patach under the ayin) — right: a noun, not a numeral; its tenth is the compile's arithmetic

# THE FRAMES AND THE REGISTER
FR = [(c, v) for (c, v) in SPAN if words('Num', c, v)[0] in ('וידבר', 'ויאמר') and words('Num', c, v)[1] == 'יהוה']
FR_SAID = [(c, v) for c, v in FR if words('Num', c, v)[0] == 'ויאמר']
FR_AARON = [(c, v) for c, v in FR if words('Num', c, v)[2:4] == ['אל', 'אהרן']]
REG = {}
for (c, v) in SPAN:
    vs = [(x, [q for q in m.split('/') if 'V' in q][0]) for x, m in by[('Num', c, v)] if m and re.search(r'V.w', m)]
    if vs: REG[(c, v)] = [f'{x} ("{sg(c, v, x)}", {m})' for x, m in vs]
def register(c, lo, hi): return '; '.join(f'{c}:{v} ' + ', '.join(REG[(c, v)]) for v in range(lo, hi + 1) if (c, v) in REG) or 'no narrative verb'

# ---- THE MEASURED FACTS (printed by the first pass — scratchpad korach_measure1.out — then typed here as asserts; assert_driver.py
# runs every statement and lists every failure at once) ----
assert FR == [(16, 20), (16, 23), (17, 1), (17, 9), (17, 16), (17, 25), (18, 1), (18, 8), (18, 20), (18, 25)] and FR_SAID == [(17, 25), (18, 1), (18, 20)] and FR_AARON == [(18, 1), (18, 8), (18, 20)] and words('Num', 16, 20)[2:5] == ['אל', 'משה', 'ואל'], (FR, FR_SAID, FR_AARON)
assert len(REG) == 49 and Counter(c for c, v in REG) == {16: 24, 17: 21, 18: 4} and len(REG[(17, 23)]) == 5 and sorted(k for k in REG if k[0] == 18) == [(18, 1), (18, 8), (18, 20), (18, 25)], (len(REG), Counter(c for c, v in REG))
assert [(x, m) for x, m in by[('Num', 16, 4)] if m and 'V' in m] == [('וישמע', 'HC/Vqw3ms'), ('ויפל', 'HC/Vqw3ms')] and by[('Num', 16, 22)][0] == ('ויפלו', 'HC/Vqw3mp') and [(x, m) for x, m in by[('Num', 17, 10)] if m and 'V' in m][-1] == ('ויפלו', 'HC/Vqw3mp')   # Moses ALONE on his face at 16:4 (singular); Moses and Aaron at 16:22 and 17:10 (plural)
# CHAPTER 16
assert phrase(['ויקח', 'קרח'], None) == ['Num 16:1'] and aramaic(16, 1)[:2] == ['ואתפלג', 'קרח'] and words('Num', 16, 1)[:8] == ['ויקח', 'קרח', 'בן', 'יצהר', 'בן', 'קהת', 'בן', 'לוי'] and words('1Chr', 6, 23) == ['בן', 'יצהר', 'בן', 'קהת', 'בן', 'לוי', 'בן', 'ישראל'] and words('Exod', 6, 21) == ['ובני', 'יצהר', 'קרח', 'ונפג', 'וזכרי']   # "and Korach TOOK" — no object; Onkelos supplies "and he DIVIDED himself"; the genealogy stops at Levi where Chronicles runs on to Israel (1 Chr 6:23 — Heman's line, Samuel's)
assert hits('יצהר', None, True) == ['1Chr 23:12', '1Chr 23:18', '1Chr 5:28', '1Chr 6:23', '2Kgs 18:32', 'Exod 6:21', 'Jer 31:12', 'Joel 1:10', 'Num 16:1', 'Num 18:12'] and [x for x in byp[('Num', 16, 1)] if plain(x) == 'יצהר'] == [x for x in byp[('Num', 18, 12)] if plain(x) == 'יצהר'] == ['יִצְהָר']   # IZHAR / FRESH OIL — Korach's father's name and the priests' due at 18:12 are ONE POINTED WORD (the bare token's ten seats: the name at Exodus, Numbers and Chronicles; the oil at Kings, Jeremiah, Joel and 18:12)
assert phrase(['חמשים', 'ומאתים'], None) == ['2Chr 8:10', 'Exod 30:23', 'Ezek 48:17', 'Num 16:17', 'Num 16:2', 'Num 26:10'] and phrase(['החמשים', 'ומאתים'], None) == ['Num 16:35'] and RIGHT[(16, 2)] == [250] and RIGHT[(16, 17)] == [250] and GAPS[(16, 35)] == [200]   # "fifty and two hundred" at six seats (the anointing oil's cinnamon and cane, Exod 30:23, among them); THE ARTICLE-FORM "the fifty and two hundred" at 16:35 alone — the parser reads 200
ART_CHAIN = sorted({f'{b} {c}:{v}' for (b, c, v), ws in by.items() for i, (x, _) in enumerate(ws[:-1]) if x.startswith('ה') and x[1:] in ('חמשים', 'עשרים', 'שלשים', 'ארבעים', 'ששים', 'שבעים', 'שמנים', 'תשעים', 'מאה', 'מאתים', 'שש', 'שבע', 'שלש', 'ארבע', 'חמש', 'עשר', 'עשרה') and ws[i + 1][0].startswith('ו')})
assert ART_CHAIN == ['1Chr 27:6', '1Kgs 19:19', '2Kgs 1:10', '2Sam 20:10', '2Sam 2:23', '2Sam 3:27', '2Sam 4:6', 'Neh 11:25', 'Neh 12:39', 'Num 16:35'] and [s for s in ART_CHAIN if key(s)[0] in T] == ['Num 16:35'], ART_CHAIN   # the article on a numeral before a conjoined word — ten candidate seats, one in the Torah: the compile's parser item
assert phrase(['נשיאי', 'עדה'], None) == ['Num 16:2'] and phrase(['קראי', 'מועד'], None) == ['Num 16:2'] and phrase(['קריאי', 'העדה'], None) + phrase(['קרואי', 'העדה'], None) == ['Num 1:16', 'Num 26:9'] and phrase(['אנשי', 'שם'], None) == ['Num 16:2'] and aramaic(16, 2)[7:12] == ['וחמשין', 'רברבי', 'כנשתא', 'מערעי', 'זמן']   # "princes of the congregation, called to the assembly, men of name" — three one-seat phrases; the census's "called of the congregation" (1:16, the ketiv/qere seat) returns at 26:9 of Dathan and Abiram
assert phrase(['רב', 'לכם'], None) == ['1Kgs 12:28', 'Deut 1:6', 'Deut 2:3', 'Deut 3:19', 'Ezek 44:6', 'Ezek 45:9', 'Num 16:3', 'Num 16:7'] and phrase(['רב', 'לך'], None) == ['Deut 3:26'] and phrase(['כל', 'העדה', 'כלם', 'קדשים'], None) == ['Num 16:3'] and hits('תתנשאו', None, True) == ['Num 16:3'] and aramaic(16, 3)[7:9] == ['סגי', 'לכון'] and aramaic(16, 3)[14:18] == ['וביניהון', 'שריא', 'שכנתא', 'דיי']   # "TOO MUCH FOR YOU" — Korach's word at 16:3 returned by Moses at 16:7 (the pair's eight seats: Jeroboam's 1 Kgs 12:28 among them); "too much for YOU" said to Moses at Deut 3:26; "the LORD is among them" → the SHEKHINAH DWELLS among them
assert phrase(['ויפל', 'על', 'פניו'], None) == ['1Kgs 18:7', '1Sam 17:49', '2Sam 9:6', 'Josh 7:6', 'Num 16:4'] and phrase(['ויפלו', 'על', 'פניהם'], None) == ['1Kgs 18:39', 'Judg 13:20', 'Lev 9:24', 'Num 16:22', 'Num 17:10', 'Num 20:6']   # Moses alone on his face (16:4); the two together at 16:22, 17:10 (and Meribah's 20:6)
assert phrase(['בקר', 'וידע'], None) == ['Num 16:5'] and hits('הקדוש', T, True) == ['Num 16:5', 'Num 16:7'] and phrase(['יקריב', 'אליו'], None) == ['Num 16:5'] and aramaic(16, 5)[7:8] == ['בצפרא'] and aramaic(16, 5)[10:13] == ['ית', 'דכשר', 'ליה'] and aramaic(16, 5)[-1] == 'לשמושיה' and words('Ps', 106, 16)[-3:] == ['לאהרן', 'קדוש', 'יהוה']   # "MORNING, and the LORD will make known" — one seat; "THE holy one" (the article-form of a person) in the Torah at 16:5, 16:7 alone — and Psalm 106:16 calls Aaron "the holy one of the LORD"; Onkelos "who is FIT for Him", "to His SERVICE"
MACHTAH = [(c, v, x) for (c, v) in SPAN for x in words('Num', c, v) if 'מחת' in x]
assert len(MACHTAH) == 10 and [f'{c}:{v}' for c, v, _ in MACHTAH] == ['16:6', '16:17', '16:17', '16:17', '16:17', '16:18', '17:2', '17:3', '17:4', '17:11'] and phrase(['איש', 'מחתתו'], None) == ['Lev 10:1', 'Num 16:17', 'Num 16:18'] and nphrase(['איש', 'מחתתו'], 'Num', 16, 17) == 3 and phrase(['אש', 'זרה'], None) == ['Lev 10:1', 'Num 26:61', 'Num 3:4']   # THE CENSER ten times in the portion, four in 16:17 alone; "EACH HIS CENSER" — Nadab and Abihu's phrase (Lev 10:1) at 16:17, 16:18 and nowhere else; their "strange fire" at Lev 10:1, Num 3:4, 26:61
KETORET = [(c, v) for (c, v) in SPAN for x in words('Num', c, v) if 'קטרת' in x]
assert KETORET == [(16, 7), (16, 17), (16, 18), (16, 35), (17, 5), (17, 11), (17, 12)] and hits('מחר', ('Num',), True) == ['Num 14:25', 'Num 16:16', 'Num 16:7', 'Num 33:33']   # the incense seven times; "tomorrow" — Korach's word twice (16:7, 16:16)
assert phrase(['המעט', 'מכם'], None) == ['Ezek 34:18', 'Isa 7:13', 'Num 16:9'] and hits('המעט', None, True) == ['Deut 7:7', 'Ezek 16:20', 'Ezek 34:18', 'Gen 30:15', 'Isa 7:13', 'Job 15:11', 'Josh 22:17', 'Num 13:18', 'Num 16:13', 'Num 16:9', 'Num 35:8'] and aramaic(16, 9)[0] == aramaic(16, 13)[0] == 'הזער'   # "IS IT TOO LITTLE" — Moses to Korach (16:9) answered by Dathan to Moses (16:13) in the same word (the spies' "few" of 13:18, Leah's of Gen 30:15 its other Torah seats); Onkelos one word for both
